INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 62 anos, hipertenso, diabético e ex-tabagista, procura o pronto-atendimento com história de dor retroesternal em aperto iniciada há 2 horas, de forte intensidade, com irradiação para mandíbula e sudorese profusa. Ao exame físico: PA 165/95 mmHg, FC 88 bpm, saturação de oxigênio 94% em ar ambiente. Estase jugular ausente e pulmões limpos. O eletrocardiograma (ECG) de 12 derivações revela supradesnivelamento do segmento ST de 3 mm nas derivações V1 a V4. O hospital dispõe de serviço de hemodinâmica ativo nas 24 horas. Com base nas diretrizes atuais de Síndrome Coronariana Aguda, a conduta inicial mais adequada é:", "options": {"a": "Administração imediata de fibrinolítico (Tenecteplase) devido ao tempo de dor.", "b": "Encaminhamento imediato para cineangiocoronariografia com objetivo de realizar intervenção coronária percutânea (ICP) primária.", "c": "Solicitação imediata de marcadores de necrose miocárdica e aguardar o resultado para decidir a conduta.", "d": "Administração de doses elevadas de betabloqueador venoso para controle da pressão arterial e da angina.", "e": "Realização de teste ergométrico de urgência para confirmar a área de isquemia."}, "answer": "b", "rationale": "O paciente apresenta um Infarto Agudo do Miocárdio com Supradesnivelamento do Segmento ST (IAMCSST) de parede anterior (V1-V4). Em hospitais com serviço de hemodinâmica disponível, a Intervenção Coronária Percutânea (ICP) primária é o tratamento de escolha, devendo ser realizada preferencialmente em menos de 90 minutos do contato médico (ou 120 minutos se houver necessidade de transporte).", "option_rationales": {"a": "Incorreta. O fibrinolítico é reservado para casos onde a ICP primária não pode ser realizada no tempo preconizado (120 min).", "b": "Correta. Estratégia preferencial em centros com hemodinâmica disponível.", "c": "Incorreta. No IAMCSST, o diagnóstico é eletrocardiográfico e a conduta de reperfusão não deve aguardar marcadores.", "d": "Incorreta. Betabloqueadores venosos agudos são contraindicados se houver risco de choque ou sinais de insuficiência cardíaca; o foco deve ser a reperfusão.", "e": "Incorreta. Teste ergométrico é contraindicado na fase aguda da síndrome coronariana aguda com supra de ST."}, "difficulty": "dificil", "tags": ["Cardiologia", "SCA", "IAMCSST", "ICP"]}', 0, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente feminina, 74 anos, com antecedentes de doença renal crônica estágio 3, procura a emergência com quadro de dispneia súbita e cansaço aos pequenos esforços há 24 horas. Nega dor torácica típica. Ao exame físico: PA 110/70 mmHg, FC 110 bpm, FR 24 irpm, presença de estertores crepitantes em bases pulmonares e B3 na ausculta cardíaca. O ECG demonstra inversão profunda e simétrica de onda T em V2 a V6, sem desvios do segmento ST. Troponina ultrassensível elevada acima do percentil 99. De acordo com o quadro clínico e os achados complementares, qual a principal suspeita diagnóstica e a classificação da síndrome coronariana?", "options": {"a": "Angina instável de baixo risco, manejo ambulatorial.", "b": "Infarto agudo do miocárdio com supra de ST, parede anterior.", "c": "Infarto agudo do miocárdio sem supradesnivelamento do segmento ST (IAMSSST) - equivalente anginoso.", "d": "Miocardite aguda por provável infecção viral prévia.", "e": "Insuficiência cardíaca descompensada sem relação com isquemia miocárdica."}, "answer": "c", "rationale": "Pacientes idosos, diabéticos e renais crônicos frequentemente apresentam apresentações atípicas de SCA, conhecidas como ''equivalentes anginosos'' (ex: dispneia súbita). A inversão profunda de onda T em derivações anteriores (padrão de Wellens ou isquemia subendocárdica grave) associada à elevação de troponina confirma o IAMSSST. A presença de B3 e estertores indica insuficiência cardíaca associada, classificando o evento como de alto risco.", "option_rationales": {"a": "Incorreta. A elevação de troponina exclui angina instável e confirma infarto.", "b": "Incorreta. O ECG não mostra supradesnivelamento de ST, mas sim inversão de onda T.", "c": "Correta. A dispneia é o equivalente anginoso e os achados laboratoriais/ECG confirmam IAMSSST.", "d": "Incorreta. Embora a miocardite eleve troponina, o contexto e o ECG são mais típicos de doença coronariana isquêmica.", "e": "Incorreta. A elevação de troponina e as alterações dinâmicas no ECG apontam para isquemia como causa da descompensação."}, "difficulty": "dificil", "tags": ["Cardiologia", "IAMSSST", "Idoso", "Equivalente Anginoso"]}', 1, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um homem de 55 anos, tabagista e obeso, é admitido com dor torácica instável há 6 horas. O ECG inicial é normal. A primeira troponina colhida na admissão é negativa. Após 3 horas, o paciente apresenta recorrência da dor retroesternal, e o novo ECG revela depressão do segmento ST de 1 mm em DII, DIII e aVF. A troponina serada agora está acima do valor de referência. Qual a estratégia de estratificação de risco e o tempo alvo para intervenção coronária invasiva segundo a última diretriz brasileira e europeia?", "options": {"a": "Estratégia ultra-precoce: cineangiocoronariografia em até 2 horas.", "b": "Estratégia precoce: cineangiocoronariografia em até 24 horas.", "c": "Estratégia tardia: cineangiocoronariografia em até 72 horas.", "d": "Estratégia conservadora: realizar apenas após teste de isquemia não invasivo positivo.", "e": "Tratamento clínico exclusivo, sem necessidade de intervenção invasiva imediata."}, "answer": "b", "rationale": "O paciente apresenta IAMSSST com critérios de alto risco: alteração dinâmica do segmento ST e curva de marcadores positiva. Para pacientes com diagnóstico confirmado de IAMSSST e pelo menos um critério de alto risco (como a alteração dinâmica de ST), a recomendação é a estratégia invasiva precoce em até 24 horas.", "option_rationales": {"a": "Incorreta. Reservada para pacientes com instabilidade hemodinâmica, choque, dor refratária ou arritmias graves (emergência < 2h).", "b": "Correta. Diagnóstico confirmado de IAMSSST com alto risco exige intervenção em 24h.", "c": "Incorreta. A estratégia de 72h é para pacientes de risco intermediário sem as características citadas.", "d": "Incorreta. IAMSSST de alto risco exige estratégia invasiva direta.", "e": "Incorreta. A intervenção invasiva reduz desfechos em pacientes de alto risco."}, "difficulty": "dificil", "tags": ["Cardiologia", "SCA", "IAMSSST", "Estratificação de Risco"]}', 2, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 50 anos, sem comorbidades conhecidas, apresenta dor torácica súbita e intensa, tipo rasgante, com irradiação para as costas. Ao ser avaliado pelo SAMU, o ECG demonstra supradesnivelamento do segmento ST de 2 mm em DII, DIII e aVF. Durante o transporte, nota-se diferença de pressão arterial entre os braços (180/100 mmHg no direito e 130/80 mmHg no esquerdo). Diante dessa suspeita clínica, qual a conduta imediata MAIS prudente antes da reperfusão?", "options": {"a": "Administrar dupla antiagregação plaquetária com aspirina e clopidogrel imediatamente.", "b": "Realizar trombólise química com Tenecteplase o mais rápido possível.", "c": "Realizar angiotomografia de tórax ou ecocardiograma transesofágico para excluir dissecção aguda de aorta.", "d": "Administrar heparina não fracionada em bólus endovenoso.", "e": "Encaminhar para ICP primária sem exames adicionais, focando no ''tempo-porta-balão''."}, "answer": "c", "rationale": "Embora o ECG sugira um infarto inferior, a história clínica de dor ''rasgante'' irradiada para as costas e a assimetria de pulsos/pressão são sinais clássicos de dissecção aguda de aorta (tipo A). A dissecção pode envolver o óstio da artéria coronária direita, gerando o supra de ST inferior. Administrar antiagregantes ou fibrinolíticos nesse cenário seria catastrófico. O diagnóstico diferencial deve ser selado antes de qualquer terapia antitrombótica.", "option_rationales": {"a": "Incorreta. Perigoso se o diagnóstico for dissecção de aorta.", "b": "Incorreta. Contraindicação absoluta se houver dissecção de aorta.", "c": "Correta. Segurança diagnóstica em caso de alta suspeita de dissecção (diagnóstico diferencial crítico).", "d": "Incorreta. Aumenta o risco de tamponamento em caso de dissecção.", "e": "Incorreta. Embora o IAM seja urgente, a dissecção é uma ''armadilha'' clássica que deve ser excluída em exames de imagem se suspeitada."}, "difficulty": "dificil", "tags": ["Cardiologia", "IAMCSST", "Dissecção de Aorta", "Diagnóstico Diferencial"]}', 3, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente feminina, 68 anos, admitida com IAMCSST de parede inferior há 4 horas. Realizada ICP com sucesso na coronária direita. No segundo dia de internação, a paciente evolui com hipotensão súbita, dispneia intensa, estertores crepitantes bilaterais e um novo sopro holossistólico rude em borda esternal esquerda baixa, associado a frêmito. Não há distensão jugular importante. Qual a complicação mecânica mais provável?", "options": {"a": "Ruptura de parede livre do ventrículo esquerdo.", "b": "Ruptura de septo interventricular.", "c": "Disfunção/ruptura de músculo papilar com insuficiência mitral aguda.", "d": "Aneurisma de ventrículo esquerdo.", "e": "Pseudoaneurisma de ventrículo esquerdo."}, "answer": "b", "rationale": "A ruptura de septo interventricular (CIV pós-infarto) manifesta-se tipicamente com choque cardiogênico, edema agudo de pulmão e um sopro holossistólico em borda esternal esquerda. O frêmito é comum. A insuficiência mitral aguda (opção C) também causa sopro e edema, mas o sopro é tipicamente em foco mitral com irradiação para a axila, e a ruptura septal é uma associação clássica com o sopro em borda esternal.", "option_rationales": {"a": "Incorreta. Ruptura de parede livre costuma levar a tamponamento cardíaco súbito e atividade elétrica sem pulso (AESP), sem sopro holossistólico e com pulmões limpos.", "b": "Correta. Localização do sopro e quadro clínico apontam para CIV pós-IAM.", "c": "Incorreta. A insuficiência mitral aguda por ruptura de papilar causa sopro sistólico apical irradiado para axila, não em borda esternal esquerda.", "d": "Incorreta. Aneurismas são complicações tardias (semanas) e não causam sopro holossistólico agudo com choque.", "e": "Incorreta. Pseudoaneurisma é uma ruptura contida pela pleura/pericárdio, raro causar este sopro específico."}, "difficulty": "dificil", "tags": ["Cardiologia", "IAM", "Complicações Mecânicas", "Choque Cardiogênico"]}', 4, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 45 anos, tabagista, sem outras comorbidades, é admitido com dor torácica típica e supra de ST de 4 mm em V1-V6. Realizada trombólise com sucesso (critérios de reperfusão presentes). No entanto, o paciente permanece em classe funcional Killip IV (choque cardiogênico). De acordo com o estudo SHOCK e as diretrizes vigentes, qual a melhor estratégia a seguir?", "options": {"a": "Manter tratamento clínico com inotrópicos e observar por 24 horas.", "b": "Realizar nova tentativa de trombólise com dose dobrada.", "c": "Encaminhamento imediato para cineangiocoronariografia e revascularização (ICP ou cirurgia) independente do tempo da trombólise.", "d": "Indicar balão intra-aórtico (BIA) e aguardar estabilização para intervenção após 48 horas.", "e": "Prescrever apenas anticoagulação plena e betabloqueador venoso."}, "answer": "c", "rationale": "Em pacientes com infarto agudo do miocárdio complicado por choque cardiogênico, a revascularização precoce (seja por ICP ou cirurgia) reduz a mortalidade em 6 meses a 1 ano (conforme estudo SHOCK). Mesmo após trombólise (independente do sucesso aparente da lise), a presença de choque exige abordagem invasiva imediata.", "option_rationales": {"a": "Incorreta. Tratamento clínico isolado no choque cardiogênico tem mortalidade altíssima.", "b": "Incorreta. Trombólise repetida aumenta risco de sangramento sem benefício estabelecido no choque.", "c": "Correta. Revascularização precoce é mandatória no choque cardiogênico pós-IAM.", "d": "Incorreta. O BIA não deve retardar a revascularização definitiva; evidências recentes (IABP-SHOCK II) questionam seu benefício rotineiro.", "e": "Incorreta. Betabloqueadores são contraindicados no choque Killip IV."}, "difficulty": "dificil", "tags": ["Cardiologia", "Choque Cardiogênico", "IAMCSST", "Invasivo"]}', 5, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 59 anos, obeso e hipertenso, em uso de AAS e estatina, apresenta-se com episódios de dor torácica aos pequenos esforços nas últimas 48 horas, com duração de 15 minutos. ECG na admissão demonstra infraestruturamento de ST de 0,5 mm em V4-V6. Troponina inicial discretamente elevada. O escore de risco GRACE é de 145 pontos. Além da antiagregação plaquetária e anticoagulação, qual a conduta em relação ao uso de clopidogrel ou outros bloqueadores P2Y12 se a cineangiocoronariografia for planejada para as próximas 12 horas?", "options": {"a": "Administrar dose de ataque de Ticagrelor imediatamente (upstream).", "b": "Aguardar a cineangiocoronariografia e administrar o bloqueador P2Y12 apenas após o conhecimento da anatomia coronária, conforme diretrizes mais recentes para IAMSSST.", "c": "Administrar dose de ataque de Prasugrel imediatamente.", "d": "Administrar apenas Clopidogrel, pois Prasugrel e Ticagrelor são contraindicados no IAMSSST.", "e": "Não utilizar nenhum bloqueador P2Y12, mantendo apenas AAS."}, "answer": "b", "rationale": "As diretrizes recentes (ESC 2020 e atualizações brasileiras) sugerem que no IAMSSST, onde a anatomia coronária será conhecida em curto prazo (< 24h), o pré-tratamento de rotina com inibidores P2Y12 (especialmente se houver chance de cirurgia de urgência) pode ser omitido até o cateterismo. O Prasugrel, especificamente, só deve ser dado após a anatomia ser conhecida. O Ticagrelor pode ser considerado em alguns casos, mas a tendência atual é o ''no-pretreatment'' em centros com acesso rápido ao cateterismo.", "option_rationales": {"a": "Incorreta. O uso ''upstream'' de rotina no IAMSSST vem perdendo força devido ao risco hemorrágico sem benefício isquêmico claro em todos os grupos.", "b": "Correta. Tendência atual de aguardar anatomia coronária no IAMSSST se o cateterismo for precoce.", "c": "Incorreta. Prasugrel é contraindicado antes de conhecer a anatomia no IAMSSST.", "d": "Incorreta. Falsa; Ticagrelor e Prasugrel são preferidos sobre o Clopidogrel se não houver contraindicação.", "e": "Incorreta. O bloqueador P2Y12 é necessário para o tratamento, a questão é o momento do início."}, "difficulty": "dificil", "tags": ["Cardiologia", "IAMSSST", "Antiagregação", "Farmacologia"]}', 6, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 38 anos, usuário de cocaína, admite-se com dor torácica intensa há 1 hora. O ECG mostra elevação do segmento ST de 2 mm em derivações laterais (D1, aVL, V5, V6). PA 170/110 mmHg, FC 120 bpm. Qual a primeira linha de tratamento farmacológico para o controle da dor e da pressão arterial, e qual medicação deve ser EVITADA sistematicamente nesse contexto?", "options": {"a": "Primeira linha: Betabloqueadores venosos (Metoprolol); Evitar: Nitratos.", "b": "Primeira linha: Nitroglicerina e Benzodiazepínicos; Evitar: Betabloqueadores.", "c": "Primeira linha: Morfina e AAS; Evitar: Anticoagulantes.", "d": "Primeira linha: Bloqueadores de canais de cálcio; Evitar: Benzodiazepínicos.", "e": "Primeira linha: Trombolíticos; Evitar: Estatinas."}, "answer": "b", "rationale": "No infarto induzido por cocaína, há um estado adrenérgico exacerbado. O uso de betabloqueadores (opção A) pode causar estimulação alfa-adrenérgica não oposicionada, levando a piora do vasoespasmo coronariano e sistêmico. O tratamento inicial deve focar em nitratos (vasodilatação) e benzodiazepínicos (redução do drive simpático).", "option_rationales": {"a": "Incorreta. Betabloqueadores são perigosos pelo risco de efeito alfa puro.", "b": "Correta. Protocolo padrão para SCA associada à cocaína.", "c": "Incorreta. Anticoagulantes são indicados se houver infarto confirmado.", "d": "Incorreta. Bloqueadores de cálcio podem ser usados, mas benzodiazepínicos são preferenciais para o drive central.", "e": "Incorreta. Trombólise deve ser evitada pela alta prevalência de vasoespasmo sem trombo fixo e risco de hemorragia por picos hipertensivos."}, "difficulty": "dificil", "tags": ["Cardiologia", "SCA", "Cocaína", "Betabloqueadores"]}', 7, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Em um paciente com IAMCSST de parede inferior, o ECG de derivações direitas (V3R e V4R) revela supradesnivelamento de ST de 1 mm em V4R. O paciente apresenta PA 85/50 mmHg e pulmões limpos. Qual o tratamento imediato para a hipotensão e qual classe de medicação é CONTRAINDICADA?", "options": {"a": "Tratamento: Furosemida venosa; Contraindicada: Dopamina.", "b": "Tratamento: Volume (Salina 0,9%) endovenoso; Contraindicada: Nitratos/Diuréticos.", "c": "Tratamento: Dobutamina; Contraindicada: Heparina.", "d": "Tratamento: Atropina; Contraindicada: Aspirina.", "e": "Tratamento: Noradrenalina; Contraindicada: Clopidogrel."}, "answer": "b", "rationale": "O supradesnivelamento em V4R confirma o diagnóstico de Infarto de Ventrículo Direito (VD). O VD infartado é dependente de pré-carga para manter o débito cardíaco para o pulmão e, consequentemente, para o VE. Por isso, a infusão de volume é o tratamento inicial para a hipotensão. Nitratos e diuréticos reduzem a pré-carga e podem agravar severamente o choque no infarto de VD.", "option_rationales": {"a": "Incorreta. Furosemida piora a situação por reduzir a pré-carga.", "b": "Correta. Manejo clássico do infarto de VD.", "c": "Incorreta. Inotrópicos podem ser usados se volume falhar, mas volume é o primeiro passo.", "d": "Incorreta. Atropina é para bradiarritmias.", "e": "Incorreta. Noradrenalina pode ser necessária no choque refratário, mas volume é o pilar inicial."}, "difficulty": "dificil", "tags": ["Cardiologia", "Infarto de VD", "IAMCSST", "Manejo"]}', 8, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 62 anos, DM2, apresenta quadro de IAMSSST. Cineangiocoronariografia mostra lesão de 90% em tronco de coronária esquerda e lesões triarteriais complexas. O cálculo do Syntax Score resulta em 34 pontos. O Heart Team se reúne para decidir a conduta. Segundo os principais estudos (como o SYNTAX trial), qual a melhor modalidade de revascularização para este paciente visando redução de eventos maiores a longo prazo?", "options": {"a": "Intervenção Coronária Percutânea (ICP) com stents farmacológicos de última geração.", "b": "Cirurgia de Revascularização do Miocárdio (CRVM).", "c": "Tratamento clínico otimizado apenas, sem revascularização.", "d": "Angioplastia APENAS da lesão culpada, sem tratar as demais.", "e": "Uso de fibrinolíticos sistêmicos."}, "answer": "b", "rationale": "Para pacientes com doença coronariana complexa (Syntax Score alto - > 22 no contexto de tronco ou > 32 no triarterial) e portadores de diabetes, a Cirurgia de Revascularização do Miocárdio (CRVM) apresenta melhores resultados a longo prazo em termos de redução de morte e infarto em comparação à ICP. O Syntax de 34 indica alta complexidade anatômica.", "option_rationales": {"a": "Incorreta. ICP em Syntax Score alto tem maior taxa de re-intervenção e eventos em comparação à cirurgia.", "b": "Correta. Recomendação classe I para anatomia complexa e diabéticos.", "c": "Incorreta. A revascularização é superior ao tratamento clínico em lesões de tronco ou triarteriais graves.", "d": "Incorreta. A revascularização completa é o objetivo no paciente estável/estabilizado.", "e": "Incorreta. Fibrinolíticos não têm papel na doença coronariana estável ou IAMSSST."}, "difficulty": "dificil", "tags": ["Cardiologia", "Diabetes", "Revascularização", "Syntax Score"]}', 9, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 42 anos, sexo masculino, hígido, apresenta-se à emergência com dor torácica de início súbito há 3 horas, após estresse emocional intenso. O ECG revela supradesnivelamento do segmento ST em V2 a V5. A cineangiocoronariografia é realizada imediatamente e não demonstra obstruções coronárias significativas (coronárias ''lisas''). O ecocardiograma revela discinesia/hipocinesia apical com aspecto de balonamento sistólico. Qual o diagnóstico mais provável?", "options": {"a": "Infarto agudo do miocárdio tipo 1 (ruptura de placa).", "b": "Miocardiopatia de Takotsubo (Síndrome do Coração Partido).", "c": "Angina de Prinzmetal.", "d": "Péssima técnica de realização do ECG.", "e": "Infarto tipo 2 por espasmo coronário persistente."}, "answer": "b", "rationale": "A Síndrome de Takotsubo é uma causa importante de MINOCA (Infarto do Miocárdio sem Obstrução Coronária). É caracterizada por alterações eletrocardiográficas e elevação de troponina que mimetizam um infarto, mas com coronárias normais e um padrão ecocardiográfico típico de balonamento apical (ventriculografia com aspecto de armadilha de polvo - Takotsubo). É frequentemente desencadeada por estresse físico ou emocional.", "option_rationales": {"a": "Incorreta. O tipo 1 exige a presença de placa aterosclerótica rota/obstrutiva.", "b": "Correta. Quadro clínico e ecocardiográfico patognomônico.", "c": "Incorreta. Angina de Prinzmetal causa supra de ST transitório por espasmo, mas não costuma causar o balonamento apical persistente do Takotsubo.", "d": "Incorreta. O quadro clínico e exames confirmam patologia real.", "e": "Incorreta. Embora o espasmo possa ocorrer, o Takotsubo é uma entidade clínica distinta pela sua morfologia ventricular típica."}, "difficulty": "dificil", "tags": ["Cardiologia", "Takotsubo", "MINOCA", "SCA"]}', 10, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente feminina, 55 anos, hipertensa e tabagista, apresenta dor torácica em repouso há 1 hora. O ECG demonstra infradesnivelamento do segmento ST de 2 mm em V4-V6 e D1/aVL. Iniciado tratamento com AAS, Clopidogrel e Enoxaparina. Após 2 horas, a paciente mantém dor torácica intensa, evoluindo com hipotensão (PA 80/50 mmHg) e estertores pulmonares bilaterais. Qual a conduta imediata indicada pela gravidade clínica?", "options": {"a": "Dobrar a dose dos antiagregantes plaquetários.", "b": "Administrar dose de ataque de nitrato venoso e observar por mais 6 horas.", "c": "Estratégia invasiva de emergência (cateterismo em até 2 horas).", "d": "Realizar teste ergométrico para avaliar reserva funcional.", "e": "Aguardar a curva de troponina (6h) para confirmar infarto antes de intervir."}, "answer": "c", "rationale": "Segundo as diretrizes de IAMSSST, a presença de critérios de MUITO ALTO RISCO (instabilidade hemodinâmica, choque cardiogênico, edema agudo de pulmão recorrente, dor refratária ou arritmias fatais) exige estratégia invasiva de emergência, ou seja, cineangiocoronariografia em até 2 horas do diagnóstico, independente de biomarcadores.", "option_rationales": {"a": "Incorreta. Não resolve a causa mecânica/isquêmica aguda.", "b": "Incorreta. Nitratos são contraindicados se houver hipotensão (choque).", "c": "Correta. Indicação de urgência absoluta por instabilidade (SCA de muito alto risco).", "d": "Incorreta. Contraindicado na fase aguda instável.", "e": "Incorreta. A clínica de instabilidade precede a necessidade de confirmação por troponina."}, "difficulty": "dificil", "tags": ["Cardiologia", "IAMSSST", "Instabilidade Hemodinâmica", "Urgência"]}', 11, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A utilização de estatinas de alta potência na fase precoce (nas primeiras 24 horas) de uma Síndrome Coronariana Aguda visa, além da redução do LDL-cholesterol, efeitos pleiotrópicos. Qual destes benefícios é atribuído às estatinas no cenário agudo?", "options": {"a": "Aumento imediato da força de contração miocárdica.", "b": "Redução da inflamação vascular, melhora da função endotelial e estabilização da placa aterosclerótica.", "c": "Efeito anticoagulante idêntico à heparina.", "d": "Bloqueio direto dos receptores de angiotensina II.", "e": "Redução do risco de sangramento gastrointestinal pelos antiagregantes."}, "answer": "b", "rationale": "As estatinas, no cenário pós-SCA imediato, são prescritas independentemente do nível de LDL basal por seus efeitos pleiotrópicos. Estes incluem a estabilização da placa (impedindo novas rupturas), redução da ativação de macrófagos e citocinas inflamatórias, e melhora da vasodilatação dependente do endotélio.", "option_rationales": {"a": "Incorreta. Estatinas não são inotrópicos.", "b": "Correta. Definição clássica dos efeitos pleiotrópicos no contexto isquêmico.", "c": "Incorreta. Não substituem anticoagulantes.", "d": "Incorreta. Função dos BRAs.", "e": "Incorreta. Não possuem efeito protetor gástrico."}, "difficulty": "moderada", "tags": ["Cardiologia", "SCA", "Farmacodinâmica", "Estatinas"]}', 12, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um homem de 67 anos apresenta-se com IAMCSST de parede lateral há 10 horas. O hospital onde se encontra não possui hemodinâmica. O tempo estimado de transferência para um centro de ICP é de 3 horas. O paciente não possui contraindicações para trombólise. Qual a conduta correta quanto à reperfusão?", "options": {"a": "Transferir sem realizar trombólise, pois o cateterismo é sempre superior.", "b": "Realizar trombólise imediata na unidade atual e organizar transferência para possível ICP de resgate ou estratégia farmaco-invasiva.", "c": "Aguardar completar 12 horas de dor para decidir entre as terapias.", "d": "Iniciar apenas anticoagulação plena e não realizar reperfusão, pois já se passaram 10 horas.", "e": "Administrar apenas AAS e nitrato, aguardando melhora espontânea."}, "answer": "b", "rationale": "A reperfusão química (trombólise) está indicada se o tempo estimado do diagnóstico até a realização da ICP primária for maior que 120 minutos, em pacientes com menos de 12 horas de evolução de IAMCSST. No caso, a transferência demoraria 180 min (3h), ultrapassando os 120 min. Logo, a trombólise na unidade de origem é a conduta que prioriza o tempo de músculo poupado.", "option_rationales": {"a": "Incorreta. O atraso na transferência anularia o benefício da ICP primária.", "b": "Correta. Aplicação do protocolo de tempo de reperfusão preconizado.", "c": "Incorreta. Quanto mais cedo a reperfusão, melhor o prognóstico; 12h é o limite superior clássico.", "d": "Incorreta. Ainda há benefício de reperfusão com 10h de evolução.", "e": "Incorreta. Omissão de tratamento essencial."}, "difficulty": "dificil", "tags": ["Cardiologia", "IAMCSST", "Trombólise", "Logística"]}', 13, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente de 48 anos, masculino, portador de prótese valvar metálica em posição mitral, sob uso de varfarina (INR alvo 2,5 - 3,5), apresenta IAMSSST. Realizada ICP com colocação de stent farmacológico. De acordo com as diretrizes de ''Terapia Antitrombótica no Paciente com Necessidade de Anticoagulação Oral'', qual a estratégia recomendada durante a fase inicial pós-hospitalar para balancear risco isquêmico e hemorrágico?", "options": {"a": "Terapia tripla (Varfarina + AAS + Clopidogrel) por pelo menos 1 ano.", "b": "Terapia dupla apenas com Varfarina e AAS por 6 meses.", "c": "Terapia tripla por curto período (até 1 semana), seguida de terapia dupla (Varfarina + um inibidor P2Y12, preferencialmente Clopidogrel) por 12 meses.", "d": "Suspender a Varfarina definitivamente e manter apenas AAS e Ticagrelor.", "e": "Manter Varfarina mas reduzir o INR alvo para 1,5."}, "answer": "c", "rationale": "As evidências atuais (estudos PIONEER, REDUAL-PCI, AUGUSTUS e ENTRUST-AF) demonstram que a terapia dupla (Anticoagulante + um único antiagregante) é superior à terapia tripla clássica na redução de sangramentos sem aumento significativo de eventos isquêmicos. A recomendação padrão é manter a terapia tripla apenas durante a internação ou até 7 dias, e seguir com terapia dupla (geralmente com Clopidogrel) por 12 meses.", "option_rationales": {"a": "Incorreta. Terapia tripla por 1 ano tem risco hemorrágico inaceitável.", "b": "Incorreta. Clopidogrel é preferido ao AAS para compor a terapia dupla no contexto de ICP.", "c": "Correta. Estratégia atual de descalonamento precoce para segurança.", "d": "Incorreta. O paciente tem prótese mecânica, não pode suspender anticoagulação oral.", "e": "Incorreta. INR de 1,5 é insuficiente para proteger a valva mitral metálica."}, "difficulty": "dificil", "tags": ["Cardiologia", "SCA", "Anticoagulação", "Terapia Tripla"]}', 14, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre a utilização da oxigenioterapia na SCA, segundo os principais estudos randomizados (como o AVOID e DETO2X-AMI) e as recomendações atuais, assinale a correta:", "options": {"a": "Deve ser administrada em todos os pacientes para hiperoxigenar o miocárdio isquêmico.", "b": "Deve ser evitada se a saturação periférica de oxigênio (SpO2) for maior ou igual a 90%, pelo risco de vasoconstrição coronária e aumento do dano oxidativo.", "c": "É indicada apenas se o paciente apresentar dor refratária.", "d": "O uso de cateter de oxigênio de alto fluxo é superior à ventilação não invasiva em todos os casos de infarto.", "e": "Oxigênio deve ser iniciado apenas se SpO2 < 80% no IAMCSST."}, "answer": "b", "rationale": "Estudos demonstraram que a suplementação de oxigênio em pacientes não hipoxêmicos com IAM pode causar vasoconstrição coronária reflexa e aumentar a área de infarto pelo estresse oxidativo. Por isso, a diretriz atual recomenda O2 apenas se SpO2 < 90% ou sinais de desconforto respiratório.", "option_rationales": {"a": "Incorreta. A hiperóxia é deletéria.", "b": "Correta. Mudança de paradigma baseada em evidências sólidas.", "c": "Incorreta. Não melhora a dor se não houver hipóxia.", "d": "Incorreta. VNI tem indicações precisas (congestão grave/edema agudo).", "e": "Incorreta. O corte é 90% (algumas fontes citam 92%)."}, "difficulty": "moderada", "tags": ["Cardiologia", "SCA", "Oxigenioterapia", "Cuidados Críticos"]}', 15, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 52 anos apresenta dor torácica recorrente em repouso. O ECG de 12 derivações realizado durante o episódio de dor mostra supradesnivelamento transitório do segmento ST, que desaparece completamente após o uso de nitrato sublingual, retornando à linha de base. O paciente é tabagista, mas não tem outros fatores de risco. O cateterismo demonstra coronárias epicárdicas normais. Qual o mecanismo fisiopatológico mais provável?", "options": {"a": "Ruptura de placa lipídica instável.", "b": "Espasmo coronariano focal (Angina de Prinzmetal).", "c": "Tromboembolemia originada no átrio esquerdo.", "d": "Microangiopatia diabética.", "e": "Hipertrofia miocárdica grave."}, "answer": "b", "rationale": "A Angina de Prinzmetal (ou variante) é caracterizada por espasmo coronário intenso que leva à isquemia transmural transitória, resultando em supra de ST no ECG que cede com nitratos ou bloqueadores de canais de cálcio. A ausência de doença obstrutiva no cateterismo corrobora o componente funcional em vez de mecânico (placa).", "option_rationales": {"a": "Incorreta. Ruptura de placa causaria obstrução fixa ou trombo visível.", "b": "Correta. Quadro clínico clássico de vasoespasmo.", "c": "Incorreta. Tromboembolia causaria infarto persistente (tipo 2) e não supra dinâmico.", "d": "Incorreta. Microangiopatia não costuma causar supra de ST transitório.", "e": "Incorreta. Hipertrofia pode causar infra de ST ou supra por repolarização, mas não crises dinâmicas recorrentes com dor."}, "difficulty": "media", "tags": ["Cardiologia", "Angina de Prinzmetal", "Vasoespasmo", "SCA"]}', 16, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 70 anos, admitido com IAMCSST de parede lateral há 6 horas. O ECG revela bloqueio atrioventricular de terceiro grau (BAVT) com escape ventricular de baixa frequência (28 bpm) e instabilidade hemodinâmica. Qual a conduta imediata, além da ativação da hemodinâmica?", "options": {"a": "Administrar 1,0 mg de Atropina IV e aguardar melhora.", "b": "Marcapasso transcutâneo imediato seguido de marcapasso transvenoso se necessário.", "c": "Iniciar infusão de Amiodarona para estabilizar o ritmo.", "d": "Realizar cardioversão elétrica sincronizada.", "e": "Administrar Digital para aumentar a condução AV."}, "answer": "b", "rationale": "Bradiarritmias instáveis no contexto de infarto (especialmente em parede inferior ou com bloqueios infra-Hissianos no infarto anterior) requerem suporte imediato de marcapasso. A atropina pode ser tentada, mas em BAVT com escape ventricular lento, sua eficácia é baixa. O marcapasso transcutâneo é a medida temporária mais rápida enquanto se prepara o transvenoso.", "option_rationales": {"a": "Incorreta. Atropina raramente funciona no BAVT de QRS largo infra-Hissiano.", "b": "Correta. Suporte hemodinâmico e de ritmo mandatário.", "c": "Incorreta. Amiodarona pode piorar a bradicardia.", "d": "Incorreta. Cardioversão é para taquiarritmias.", "e": "Incorreta. Digital lentifica a condução AV, agravando o bloqueio."}, "difficulty": "moderada", "tags": ["Cardiologia", "IAMCSST", "Bradiarritmias", "Marcapasso"]}', 17, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual dos seguintes parâmetros é fundamental para o diagnóstico de Infarto Agudo do Miocárdio tipo 2?", "options": {"a": "Ruptura de placa aterosclerótica com trombo oclusivo.", "b": "Isquemia miocárdica causada por desmanteamento entre oferta e demanda de oxigênio (ex: anemia severa, taquiarritmia, hipóxia), sem evidência de evento coronário agudo tipo 1.", "c": "Presença de dor torácica por mais de 24 horas consecutivas.", "d": "Elevação de troponina em paciente com insuficiência renal crônica estável.", "e": "Uso obrigatório de trombólise."}, "answer": "b", "rationale": "A 4ª Definição Universal de Infarto classifica o tipo 2 como aquele resultante de uma condição clínica distinta da aterotrombose coronária, que gera um desequilíbrio entre a oferta de oxigênio (ex: anemia, hipotensão) e a demanda (ex: hipertensão grave, taquicardia), levando a lesão miocárdica isquêmica aguda.", "option_rationales": {"a": "Incorreta. Isso define o infarto tipo 1.", "b": "Correta. Definição universal de infarto tipo 2.", "c": "Incorreta. Temporalidade não define o tipo.", "d": "Incorreta. Elevação estável sem isquemia define lesão miocárdica crônica, não infarto agudo.", "e": "Incorreta. Trombólise não é usada rotineiramente no tipo 2."}, "difficulty": "moderada", "tags": ["Cardiologia", "IAM", "Definição Universal", "Tipo 2"]}', 18, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente feminina, 82 anos, admitida com IAMCSST anterior, chega com 8 horas de evolução de dor. Ao exame: PA 70/40 mmHg, FC 125 bpm, extremidades frias, cianose de extremidades e estertores pulmorares em 2/3 inferiores de ambos os pulmões. Classificação de Killip-Kimball desta paciente é:", "options": {"a": "Killip I.", "b": "Killip II.", "c": "Killip III.", "d": "Killip IV.", "e": "Killip V (extremo)."}, "answer": "d", "rationale": "A classificação de Killip-Kimball prediz mortalidade no IAM: Killip I (sem sinais de IC); Killip II (crepitação em bases, B3 ou turgência jugular); Killip III (Edema agudo de pulmão); Killip IV (Choque cardiogênico - hipotensão e sinais de má perfusão periférica). A paciente apresenta choque, logo é Killip IV.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta.", "d": "Correta. Presença de choque cardiogênico.", "e": "Incorreta. A escala vai apenas até IV."}, "difficulty": "facil", "tags": ["Cardiologia", "IAM", "Killip", "Prognóstico"]}', 19, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal indicação para o uso de bloqueadores dos receptores de angiotensina (BRA) ou inibidores da ECA (iECA) precocemente (primeiras 24h) na SCA?", "options": {"a": "Pacientes com fração de ejeção do ventrículo esquerdo (FEVE) ≤ 40%, hipertensão, diabetes ou doença renal crônica estável.", "b": "Apenas se houver dor torácica persistente.", "c": "Uso de rotina em pacientes com hipotensão arterial.", "d": "Em substituição à aspirina.", "e": "Para prevenir arritmias atriais em todos os casos."}, "answer": "a", "rationale": "iECA (ou BRA, se intolerância ao iECA) reduz o remodelamento ventricular e a mortalidade pós-infarto. É especialmente indicado de forma precoce em pacientes com disfunção ventricular sistólica (FE < 40%), ICC, diabetes ou hipertensão, desde que o paciente esteja hemodinamicamente estável.", "option_rationales": {"a": "Correta. Recomendação baseada em grandes estudos (SAVE, AIRE, TRACE).", "b": "Incorreta. Não são analgésicos.", "c": "Incorreta. Contraindicado na hipotensão aguda.", "d": "Incorreta. Não substituem antiagregantes.", "e": "Incorreta. Não são antiarrítmicos de primeira linha."}, "difficulty": "media", "tags": ["Cardiologia", "SCA", "iECA", "Remodelamento"]}', 20, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 60 anos, pós-IAMCSST inferior (concluído revascularização há 3 dias), apresenta no ECG de monitorização episódios de ritmo idioventricular acelerado (RIVA), com frequência cardíaca de 75 bpm. O paciente está assintomático e estável. Qual a conduta recomendada?", "options": {"a": "Administrar bólus de Lidocaína e iniciar infusão contínua.", "b": "Realizar cardioversão elétrica de urgência.", "c": "Apenas observação clínica, pois o RIVA é considerado um ritmo benigno de reperfusão.", "d": "Iniciar doses altas de Amiodarona venosa.", "e": "Indicar implante de CDI (cardioversor desfibrilador implantável)."}, "answer": "c", "rationale": "O RIVA é um ritmo ventricular com frequência entre 60 e 120 bpm, muito comum após a reperfusão coronária (especialmente após trombólise com sucesso). É considerado um ritmo benigno e autolimitado, que não altera o prognóstico e não requer tratamento antiarrítmico se o paciente estiver estável.", "option_rationales": {"a": "Incorreta. Antiarrítmicos não são necessários.", "b": "Incorreta. Paciente estável e frequência baixa não justificam choque.", "c": "Correta. Conduta expectante no RIVA.", "d": "Incorreta. Amiodarona não é indicada.", "e": "Incorreta. Sem indicação de CDI."}, "difficulty": "moderada", "tags": ["Cardiologia", "RIVA", "AM", "Arritmias"]}', 21, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual complicação do infarto é mais provável em um paciente que, subitamente, no 5º dia pós-IAM transmural extenso, apresenta atividade elétrica sem pulso (AESP) e sinais de tamponamento cardíaco (turgência jugular e abafamento de bulhas)?", "options": {"a": "Reinfarto agudo.", "b": "Ruptura de parede livre do ventrículo esquerdo.", "c": "Embolia pulmonar maciça.", "d": "Pericardite pós-infarto (Síndrome de Dressler).", "e": "Endocardite infecciosa aguda."}, "answer": "b", "rationale": "A ruptura de parede livre do VE é uma complicação catastrófica que ocorre geralmente entre o 3º e 7º dia pós-infarto transmural. Leva a hemopericárdio súbito, tamponamento e morte rápida, manifestando-se frequentemente como AESP.", "option_rationales": {"a": "Incorreta. Reinfarto não causaria tamponamento súbito.", "b": "Correta. Quadro clínico típico de ruptura de parede livre.", "c": "Incorreta. TEP causa turgência jugular, mas não abafamento de bulhas com tamponamento.", "d": "Incorreta. Dressler é uma complicação inflamatória tardia (semanas) e raramente causa tamponamento hemorrágico agudo.", "e": "Incorreta. Sem relação com o quadro descrito."}, "difficulty": "moderada", "tags": ["Cardiologia", "IAM", "Complicações", "Ruptura de Parede Livre"]}', 22, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 65 anos, hipertenso e diabético, em uso de AAS e enalapril. Admitido com dor torácica há 2 horas. ECG mostra supra de ST de 3mm em V1 a V4. Hemodinâmica disponível. Qual fármaco antiagregante inibidor do receptor P2Y12 é o MAIS recomendado pelas diretrizes brasileiras e internacionais para ser associado ao AAS nesse paciente que será submetido a ICP primária?", "options": {"a": "Clopidogrel 300 mg.", "b": "Prasugrel 60 mg ou Ticagrelor 180 mg.", "c": "Ticlopidina 500 mg.", "d": "Dipiridamol 200 mg.", "e": "Varfarina 5 mg."}, "answer": "b", "rationale": "Em pacientes com IAMCSST submetidos a ICP primária, os novos inibidores P2Y12 (Prasugrel e Ticagrelor) são superiores ao Clopidogrel na redução de eventos isquêmicos e trombose de stent, sendo a recomendação de primeira escolha (classe I) se não houver contraindicação específica (ex: risco hemorrágico muito alto, AVC prévio para o prasugrel).", "option_rationales": {"a": "Incorreta. Clopidogrel é a segunda opção, usada se novos bloqueadores não estiverem disponíveis.", "b": "Correta. Fármacos de escolha na ICP primária moderna.", "c": "Incorreta. Ticlopidina caiu em desuso por efeitos colaterais medulares.", "d": "Incorreta. Não tem papel na SCA.", "e": "Incorreta. Varfarina é anticoagulante, não antiagregante p2y12."}, "difficulty": "media", "tags": ["Cardiologia", "SCA", "Antiagregação", "Farmacoterapia"]}', 23, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 50 anos, sem história prévia, apresenta dor torácica atípica. A troponina é levemente positiva. O ECG é normal. Realizado cateterismo que mostra artérias coronárias normais. A Ressonância Magnética Cardíaca demonstra realce tardio com padrão de distribuição subepicárdico (não isquêmico). Qual o diagnóstico mais provável?", "options": {"a": "Infarto transmural clássico.", "b": "Angina Estável.", "c": "Miocardite aguda.", "d": "Síndrome de Beribéri.", "e": "Tromboembolismo Pulmonar."}, "answer": "c", "rationale": "O padrão de realce tardio na RM cardíaca ajuda a diferenciar as causas de dor torácica e troponina elevada. O padrão isquêmico é sempre subendocárdico ou transmural (território vascular). O padrão subepicárdico ou mesocárdico é característico de inflamação miocárdica (miocardite).", "option_rationales": {"a": "Incorreta. Infarto teria realce subendocárdico/transmural.", "b": "Incorreta. Angina estável não costuma elevar troponina nem gerar realce tardio persistente.", "c": "Correta. Padrão de RM compatível com miocardite.", "d": "Incorreta. Beribéri é causa de IC de alto débito, não esse padrão de RM.", "e": "Incorreta. TEP não explicaria o realce subepicárdico focal."}, "difficulty": "moderada", "tags": ["Cardiologia", "RM Cardíaca", "Miocardite", "Diagnóstico Diferencial"]}', 24, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 58 anos, apresenta dor torácica há 24 horas. ECG mostra ondas Q em V1, V2 e V3 com inversão de onda T. Troponina está em curva descendente. O ecocardiograma mostra acinesia da parede anterior e presença de trombo móvel no ápice do ventrículo esquerdo. Qual a conduta terapêutica MANDATÓRIA para a prevenção de eventos embólicos sistêmicos?", "options": {"a": "Manter apenas AAS e Clopidogrel.", "b": "Iniciar anticoagulação plena (ex: Varfarina ou DOAC) por 3 a 6 meses.", "c": "Indicar cirurgia cardíaca para retirada do trombo imediatamente.", "d": "Administrar fibrinolítico sistêmico.", "e": "Não há necessidade de tratamento específico para o trombo, pois ele costuma dissolver sozinho."}, "answer": "b", "rationale": "A presença de trombo ventricular esquerdo pós-infarto é uma indicação formal de anticoagulação oral para prevenir AVC e outras embolias sistêmicas. O tempo recomendado de tratamento é de 3 a 6 meses, seguido de nova avaliação por imagem.", "option_rationales": {"a": "Incorreta. Antiagregantes não são suficientes para tratar trombos cavitários.", "b": "Correta. Prevenção de cardioembolismo mandatória.", "c": "Incorreta. Cirurgia é reservada para casos muito específicos e raros; o tratamento inicial é clínico.", "d": "Incorreta. Fibrinólise sistêmica para trombo ventricular aumenta risco de sangramento e fragmentação do trombo.", "e": "Incorreta. O risco de embolia é alto sem tratamento."}, "difficulty": "moderada", "tags": ["Cardiologia", "IAM", "Complicações", "Trombo de VE"]}', 25, 'draft');
